import { v4 as uuidv4 } from 'uuid';
import { z } from 'zod';
import { defineRoute, NoContent } from '../http/route.js';
import { Conflict, NotFound, parseInput } from '../http/problem.js';
import { User, UserCreateInput, UserUpdateInput } from '../schemas/user.js';
import { parseCursor, encodeCursor, PaginatedList } from '../http/pagination.js';

// In-memory store for users
const users = new Map<string, typeof User._type>();
const emailIndex = new Map<string, string>();

export const createUser = defineRoute({
  path: '/users',
  method: 'post',
  request: {
    body: UserCreateInput,
  },
  responses: {
    201: User,
    409: z.string(),
    400: z.string(),
  },
  handler: async (input) => {
    const { email, name } = input.body;

    // Check for duplicate email
    if (emailIndex.has(email)) {
      throw new Conflict(
        'user-email-conflict',
        `User with email ${email} already exists`
      );
    }

    const id = uuidv4();
    const now = new Date().toISOString();
    const user = { id, email, name, createdAt: now };

    users.set(id, user);
    emailIndex.set(email, id);

    return { status: 201, body: user };
  },
});

export const getUser = defineRoute({
  path: '/users/:id',
  method: 'get',
  request: {
    params: z.object({ id: z.string().uuid() }),
  },
  responses: {
    200: User,
    404: z.string(),
  },
  handler: async (input) => {
    const { id } = input.params;

    const user = users.get(id);
    if (!user) {
      throw new NotFound('user-not-found', `User with id ${id} not found`);
    }

    return { status: 200, body: user };
  },
});

export const listUsers = defineRoute({
  path: '/users',
  method: 'get',
  request: {
    query: z.object({
      limit: z.coerce.number().int().min(1).max(100).default(20).optional(),
      cursor: z.string().optional(),
    }),
  },
  responses: {
    200: PaginatedList(User),
    400: z.string(),
  },
  handler: async (input) => {
    const limit = input.query.limit ?? 20;
    const cursor = input.query.cursor;

    let startIndex = 0;
    if (cursor) {
      startIndex = parseCursor(cursor);
    }

    const sortedUsers = Array.from(users.values()).sort(
      (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
    );

    const items = sortedUsers.slice(startIndex, startIndex + limit);
    const nextCursor = startIndex + limit < sortedUsers.length
      ? encodeCursor(startIndex + limit)
      : undefined;

    return {
      status: 200,
      body: { items, nextCursor },
    };
  },
});

export const updateUser = defineRoute({
  path: '/users/:id',
  method: 'patch',
  request: {
    params: z.object({ id: z.string().uuid() }),
    body: UserUpdateInput,
  },
  responses: {
    200: User,
    404: z.string(),
    409: z.string(),
    400: z.string(),
  },
  handler: async (input) => {
    const { id } = input.params;
    const { email, name } = input.body;

    const user = users.get(id);
    if (!user) {
      throw new NotFound('user-not-found', `User with id ${id} not found`);
    }

    // Check for duplicate email if email is being updated
    if (email && email !== user.email && emailIndex.has(email)) {
      throw new Conflict(
        'user-email-conflict',
        `User with email ${email} already exists`
      );
    }

    // Remove old email from index if changing
    if (email && email !== user.email) {
      emailIndex.delete(user.email);
      emailIndex.set(email, id);
      user.email = email;
    }

    if (name !== undefined) {
      user.name = name;
    }

    users.set(id, user);
    return { status: 200, body: user };
  },
});

export const deleteUser = defineRoute({
  path: '/users/:id',
  method: 'delete',
  request: {
    params: z.object({ id: z.string().uuid() }),
  },
  responses: {
    204: NoContent,
    404: z.string(),
  },
  handler: async (input) => {
    const { id } = input.params;

    const user = users.get(id);
    if (!user) {
      throw new NotFound('user-not-found', `User with id ${id} not found`);
    }

    emailIndex.delete(user.email);
    users.delete(id);

    return { status: 204, body: undefined };
  },
});

/**
 * Generate a simple UUID v4.
 * This is a basic implementation for demonstration purposes.
 */
export function uuidv4(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

import { describe, it, expect } from 'vitest';
import { uuidv4 } from '../../src/lib/uuid.js';

describe('uuid', () => {
  it('generates a valid UUID v4', () => {
    const uuid = uuidv4();
    expect(uuid).toMatch(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i);
  });

  it('generates unique UUIDs', () => {
    const uuid1 = uuidv4();
    const uuid2 = uuidv4();
    expect(uuid1).not.toBe(uuid2);
  });
});

